from collections import Counter
R, C = map(int, input().split())
g = [input().strip() for _ in range(R)]
cnt = Counter("".join(g))
q = int(input())
def exist(w):
    wc = Counter(w)
    if any(cnt[ch] < v for ch, v in wc.items()):
        return False
    if cnt[w[0]] > cnt[w[-1]]:
        w = w[::-1]
    L = len(w)
    seen = [[False] * C for _ in range(R)]
    def dfs(r, c, i):
        if g[r][c] != w[i]:
            return False
        if i == L - 1:
            return True
        seen[r][c] = True
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and not seen[nr][nc] and dfs(nr, nc, i + 1):
                seen[r][c] = False
                return True
        seen[r][c] = False
        return False
    return any(dfs(r, c, 0) for r in range(R) for c in range(C))
for _ in range(q):
    print("YES" if exist(input().strip()) else "NO")

