s = input().strip()
T = int(input())
n = len(s)
res = []
def dfs(i, expr, val, last):
    if i == n:
        if val == T:
            res.append(expr)
        return
    for j in range(i + 1, n + 1):
        t = s[i:j]
        if len(t) > 1 and t[0] == "0":
            break
        x = int(t)
        if i == 0:
            dfs(j, t, x, x)
        else:
            dfs(j, expr + "+" + t, val + x, x)
            dfs(j, expr + "-" + t, val - x, -x)
            dfs(j, expr + "*" + t, val - last + last * x, last * x)
dfs(0, "", 0, 0)
res.sort()
print(len(res))
for e in res:
    print(e)

R, C = map(int, input().split())
g = [input().strip() for _ in range(R)]
M = 10 ** 9 + 7
ways = [[0] * (C + 1) for _ in range(R + 1)]
for r in range(R - 1, -1, -1):
    for c in range(C - 1, -1, -1):
        if g[r][c] == "#":
            ways[r][c] = 0
        elif r == R - 1 and c == C - 1:
            ways[r][c] = 1
        else:
            ways[r][c] = (ways[r][c + 1] + ways[r + 1][c] + ways[r + 1][c + 1]) % M
print(ways[0][0])

n, k = map(int, input().split())
a = list(map(int, input().split()))
S = sum(a)
if S % k or max(a) > S // k:
    print("NO")
else:
    t = S // k
    N = 1 << n
    dp = [-1] * N
    dp[0] = 0
    for m in range(N):
        v = dp[m]
        if v < 0:
            continue
        for i in range(n):
            if not (m >> i) & 1:
                nv = v + a[i]
                if nv <= t:
                    nm = m | (1 << i)
                    if dp[nm] < 0:
                        dp[nm] = nv % t
    print("YES" if dp[N - 1] == 0 else "NO")
